package main

import("bufio";"crypto/sha256";"encoding/hex";"encoding/json";"fmt";"os";"sort";"strings";"time")
func h(s string)string{if s==""{return ""};x:=sha256.Sum256([]byte(s));return hex.EncodeToString(x[:])}
func s(v any)string{x,_:=v.(string);return x}
func n(v any)float64{x,_:=v.(float64);return x}
func permitted(k,v string)bool{if _,e:=time.Parse(time.RFC3339Nano,v);e==nil{return true};if k=="model"||k=="served"||k=="req"{switch v{case "gpt-6.1-terra","gpt-5.6-terra","gpt-6.1-sol","gpt-5.6-sol","codex/gpt-6.1-terra","codex/gpt-5.6-terra","codex/gpt-6.1-sol","codex/gpt-5.6-sol":return true}};if k=="provider"||k=="agent"{switch v{case "codex","mybuddy","dsh","pi":return true}};switch k{case "mode","why","kind","effort","tierServed","tier_served","stop":switch v{case "account","key","provider","high","xhigh","medium","low","default","priority","flex","stop","tool_calls","end_turn","system","tools","skills","memory","files","results","chat","off","cache","session","turn":return true}};return v==""}
func safe(v any,k string)any{switch x:=v.(type){case string:if permitted(k,x){return x};return map[string]any{"sha256":h(x),"bytes":len(x)};case map[string]any:m:=map[string]any{};for a,b:=range x{m[a]=safe(b,a)};return m;case []any:a:=[]any{};for _,b:=range x{a=append(a,safe(b,k))};return a;default:return x}}
func scan(path string,fn func(int,map[string]any))int{f,e:=os.Open(path);if e!=nil{panic(e)};defer f.Close();r:=bufio.NewScanner(f);r.Buffer(make([]byte,65536),32*1024*1024);line:=0;for r.Scan(){line++;var m map[string]any;if json.Unmarshal(r.Bytes(),&m)==nil{fn(line,m)}};if r.Err()!=nil{panic(r.Err())};return line}
func arm(session string)string{x:=strings.ToLower(session);if strings.Contains(x,"append"){return "session_keyword_append"};if strings.Contains(x,"moving"){return "session_keyword_moving"};if strings.Contains(x,"fullbody"){return "session_keyword_fullbody"};if strings.Contains(x,"next-turn")||strings.Contains(x,"nextturn"){return "session_keyword_nextturn"};return ""}
func main(){start,_:=time.Parse(time.RFC3339,"2026-11-02T10:08:35+08:00");end,_:=time.Parse(time.RFC3339,"2026-11-02T10:16:50+08:00");base:=os.Args[1];usage:=[]map[string]any{};routes:=map[float64][]map[string]any{};usageLines:=scan(base+"\\usage.jsonl",func(line int,m map[string]any){t,e:=time.Parse(time.RFC3339Nano,s(m["t"]));if e!=nil||t.Before(start)||!t.Before(end){return};if s(m["provider"])!="codex"{return};mod:=s(m["model"])+s(m["req"]);if !strings.Contains(mod,"terra")&&!strings.Contains(mod,"sol"){return};m["_line"]=line;usage=append(usage,m)});ids:=map[float64]bool{};for _,m:=range usage{ids[n(m["route_id"])]=true};routeLines:=scan(base+"\\routing\\2026-11-02.jsonl",func(line int,m map[string]any){id:=n(m["id"]);if ids[id]{m["_line"]=line;routes[id]=append(routes[id],m)}});sort.SliceStable(usage,func(i,j int)bool{return s(usage[i]["t"])<s(usage[j]["t"])});rows:=[]any{};for _,u:=range usage{id:=n(u["route_id"]);t,_:=time.Parse(time.RFC3339Nano,s(u["t"]));phase:="other_candidate";if t.Hour()==10&&t.Minute()==8&&(n(u["cache_read"])==47616||n(u["cache_read"])==158848){phase="runtime_fullbody_time_read_match"};if t.Hour()==10&&t.Minute()==11&&n(u["cache_read"])==47616{phase="runtime_nextturn_time_read_match"};if t.Hour()==10&&(t.Minute()==15||t.Minute()==16){phase="live_two_arms_window_candidate"};rr:=routes[id];row:=map[string]any{"time":u["t"],"usage_line":u["_line"],"route_id":id,"model":safe(u["model"],"model"),"requested":safe(u["req"],"req"),"provider":u["provider"],"agent":safe(u["agent"],"agent"),"account_sha256":h(s(u["providerAccount"])),"session_sha256":h(s(u["session"])),"native_session_sha256":h(s(u["native_session"])),"session_keyword_flag":arm(s(u["session"])),"input_uncached":u["in"],"cache_read":u["cache_read"],"prompt_total":n(u["in"])+n(u["cache_read"]),"output":u["out"],"status":u["status"],"tries_field":u["tries"],"handed_on":u["handed_on"],"retried_ms":u["retried_ms"],"phase_candidate":phase,"routing_records_found":len(rr),"usage":safe(u,"")};if len(rr)>0{latest:=rr[0];for _,r:=range rr[1:]{if n(r["seq"])>n(latest["seq"]){latest=r}};row["route"]=safe(latest,"");row["routing_line"]=latest["_line"];tries,_:=latest["tries"].([]any);order,_:=latest["order"].([]any);row["try_count"]=len(tries);row["order_count"]=len(order);ts:=[]any{};for _,z:=range tries{tr,_:=z.(map[string]any);net,_:=tr["net"].(map[string]any);ts=append(ts,map[string]any{"account_id_sha256":h(s(tr["id"])),"model":safe(tr["model"],"model"),"status":tr["status"],"http_asks":net["asks"],"again":tr["again"],"replan":tr["replan"],"gone":tr["gone"],"start":tr["start"],"error":safe(tr["error"],"error"),"fail":safe(tr["fail"],"fail")})};row["tries_summary"]=ts;osum:=[]any{};for _,z:=range order{o,_:=z.(map[string]any);osum=append(osum,map[string]any{"account_id_sha256":h(s(o["id"])),"account_who_sha256":h(s(o["who"])),"provider":safe(o["provider"],"provider"),"model":safe(o["model"],"model")})};row["order_summary"]=osum};rows=append(rows,row);brief:=map[string]any{};for _,k:=range []string{"time","phase_candidate","session_keyword_flag","route_id","model","account_sha256","session_sha256","input_uncached","cache_read","output","status","try_count","order_count","tries_summary"}{brief[k]=row[k]};json.NewEncoder(os.Stdout).Encode(brief)};out,e:=os.Create(os.Args[2]);if e!=nil{panic(e)};enc:=json.NewEncoder(out);enc.SetIndent("","  ");enc.Encode(map[string]any{"start":start,"end_exclusive":end,"usage_lines_scanned":usageLines,"routing_lines_scanned":routeLines,"candidates":len(rows),"records":rows,"limits":[]string{"All accounts examined; no inheritance of earlier target account assumption","Matching labels are time/cache-read candidates until experiment tuples confirm identity","Session strings and account identifiers SHA-256 only; no bodies or raw credentials emitted","Route.net.asks counts HTTP asks as recorded; cannot exclude unlogged upstream internal behavior"}});out.Close();fmt.Printf("candidates=%d\n",len(rows))}
